//! The write hooks of UserQuota: they run, in the write's own transaction, the hook triggers the schema
//! declares for it and stage the events it declares with `on:`.
//!
//! Generated by metaphor-schema. Do not edit manually.
//!
//! They run around the repository write: `before` the triggers keyed `before_*`, after the row is written
//! and its lifecycle hooks have run, the `after_*` triggers in file order and then the declared events,
//! all before the commit. A failure of any of them rolls the write back, so a committed write always has
//! its events and the effects of its triggers. Delivery to subscribers is the outbox relay's, at least once.
#[allow(unused_imports)]
use backbone_core::write_hooks::{payload_from_row, Change, DeclaredEvent, NotificationRequested, WriteCtx, WriteHooks};
#[allow(unused_imports)]
use backbone_core::{PersistentEntity, ServiceError, ServiceResult};

use crate::domain::entity::UserQuota;
#[allow(unused_imports)]
use crate::domain::event::declared;
use crate::application::triggers::UserQuotaTriggers;

/// What a condition that reads the writer or the time of the write evaluates against.
#[allow(dead_code)]
struct EvalCtx {
    actor: Option<String>,
    at: chrono::DateTime<chrono::Utc>,
}

/// Runs the triggers of UserQuota and stages its declared events. `triggers` is the hand-written half (`UserQuotaTriggersImpl`).
pub struct UserQuotaWriteHooks {
    triggers: std::sync::Arc<dyn UserQuotaTriggers>,
}

impl UserQuotaWriteHooks {
    /// The hooks over the hand-written half of the triggers.
    pub fn new(triggers: std::sync::Arc<dyn UserQuotaTriggers>) -> Self {
        Self { triggers }
    }
}

#[async_trait::async_trait]
impl WriteHooks<UserQuota> for UserQuotaWriteHooks {
    fn outbox_schema(&self) -> Option<&str> {
        Some("bucket")
    }

    #[allow(unused_variables, unused_assignments)]
    async fn before(&self, write: &WriteCtx, change: &mut Change<'_, UserQuota>) -> ServiceResult<()> {
        use backbone_core::row_rule as r;
        backbone_core::write_hooks::in_trigger(async {
            let old_json = change.before().and_then(|b| serde_json::to_value(b).ok());
            let old_row = old_json.as_ref().unwrap_or(&serde_json::Value::Null);
            let ctx = EvalCtx { actor: write.actor.clone(), at: chrono::Utc::now() };
            let aggregate_id = change.subject().entity_id();
            let company = write.company_of(&serde_json::to_value(change.subject()).unwrap_or(serde_json::Value::Null));
            let _ = (&ctx, &old_row, &aggregate_id, company);
            {
                let row = &serde_json::to_value(change.subject()).unwrap_or(serde_json::Value::Null);
                // `before_create`: before_create (user_quota.hook.yaml:167)
                if matches!(change, Change::Created { .. }) {
                    if let Some(entity) = change.after_mut() {
                        entity.file_count = serde_json::from_value(r::to_json(&r::Val::Num(0.0_f64)))
                            .map_err(|e| ServiceError::Validation(format!("trigger `UserQuota.before_create` could not set `file_count`: {e}")))?;
                    }
                    let row = &serde_json::to_value(change.subject()).unwrap_or(serde_json::Value::Null);
                    if let Some(entity) = change.after_mut() {
                        self.triggers.before_create__apply_tier_defaults(write, entity).await?;
                    }
                    let row = &serde_json::to_value(change.subject()).unwrap_or(serde_json::Value::Null);
                }
            }
            {
                let row = &serde_json::to_value(change.subject()).unwrap_or(serde_json::Value::Null);
                // `before_update_tier`: before_update tier (user_quota.hook.yaml:181)
                if matches!(change, Change::Updated { .. } | Change::Transitioned { .. }) && change.field_changed("tier") {
                    if let Some((old, entity)) = change.before_and_after_mut() {
                        self.triggers.before_update_tier__apply_tier_defaults(write, old, entity).await?;
                    }
                    let row = &serde_json::to_value(change.subject()).unwrap_or(serde_json::Value::Null);
                }
            }
            Ok(())
        })
        .await
    }

    #[allow(unused_variables, unused_assignments)]
    async fn after(&self, write: &WriteCtx, change: &Change<'_, UserQuota>) -> ServiceResult<()> {
        use backbone_core::row_rule as r;
        let subject = change.subject();
        let row = serde_json::to_value(subject)
            .map_err(|e| ServiceError::Internal(format!("a row could not be read for its events: {e}")))?;
        let row = &row;
        let old = change.before().and_then(|b| serde_json::to_value(b).ok());
        let old_row = old.as_ref().unwrap_or(&serde_json::Value::Null);
        let ctx = EvalCtx { actor: write.actor.clone(), at: chrono::Utc::now() };
        let aggregate_id = subject.entity_id();
        let company = write.company_of(row);
        let _ = (&aggregate_id, company);
        let _ = &ctx;

        backbone_core::write_hooks::in_trigger(async {
            // `after_create`: after_create (user_quota.hook.yaml:176)
            if matches!(change, Change::Created { .. }) {
                tracing::info!(target: "backbone::trigger", trigger = "UserQuota.after_create", correlation_id = %write.correlation_id, log_event = "quota.created", user_id = %r::to_json(&r::field(row, "user_id")), tier = %r::to_json(&r::field(row, "tier")));
                self.triggers.after_create__emit_user_quota_created_event(write, subject).await?;
            }
            // `after_update_tier`: after_update tier (user_quota.hook.yaml:185)
            if matches!(change, Change::Updated { .. } | Change::Transitioned { .. }) && change.field_changed("tier") && r::holds(&r::ne(r::field(old_row, "tier"), r::field(row, "tier"))) {
                self.triggers.after_update_tier__send_email_tier_changed(write, change.before().unwrap_or(subject), subject).await?;
                {
                    let mut data = serde_json::Map::new();
                    let mut body = String::new();
                    body.push_str("Your storage plan has been changed to ");
                    body.push_str(&r::to_text(&r::field(row, "tier")));
                    let body = Some(body);
                    let request = NotificationRequested {
                        channel: "notify".to_string(),
                        template: None,
                        body,
                        to: r::to_json(&r::Val::List(vec![r::field(row, "user_id")])),
                        data: serde_json::Value::Object(data),
                        trigger: "UserQuota.after_update_tier".to_string(),
                    };
                    write.stage(request.record("UserQuota", &aggregate_id, company, write)).await?;
                }
                tracing::info!(target: "backbone::trigger", trigger = "UserQuota.after_update_tier", correlation_id = %write.correlation_id, log_event = "quota.tier_changed", user_id = %r::to_json(&r::field(row, "user_id")), old_tier = %r::to_json(&r::field(old_row, "tier")), new_tier = %r::to_json(&r::field(row, "tier")));
                self.triggers.after_update_tier__emit_user_quota_tier_changed_event(write, change.before().unwrap_or(subject), subject).await?;
            }
            // `after_update_used_bytes`: after_update used_bytes (user_quota.hook.yaml:195)
            if matches!(change, Change::Updated { .. } | Change::Transitioned { .. }) && change.field_changed("used_bytes") && r::holds(&r::ne(r::field(old_row, "used_bytes"), r::field(row, "used_bytes"))) {
                self.triggers.after_update_used_bytes__check_warning_threshold(write, change.before().unwrap_or(subject), subject).await?;
                self.triggers.after_update_used_bytes__update_exceeded_status(write, change.before().unwrap_or(subject), subject).await?;
            }
            // `on_enter normal`: on_enter normal (user_quota.hook.yaml:15)
            if matches!(change, Change::Transitioned { to: Some(to), .. } if to == "normal") {
                self.triggers.on_enter_normal__set_last_warning_sent_at(write, change.before().unwrap_or(subject), subject).await?;
                tracing::info!(target: "backbone::trigger", trigger = "UserQuota.on_enter normal", correlation_id = %write.correlation_id, log_event = "quota.normal", user_id = %r::to_json(&r::field(row, "user_id")));
            }
            // `on_enter exceeded`: on_enter exceeded (user_quota.hook.yaml:22)
            if matches!(change, Change::Transitioned { to: Some(to), .. } if to == "exceeded") {
                {
                    let mut data = serde_json::Map::new();
                    let mut body = String::new();
                    body.push_str("Your storage quota has been exceeded. Please upgrade or remove files.");
                    let body = Some(body);
                    let request = NotificationRequested {
                        channel: "notify".to_string(),
                        template: None,
                        body,
                        to: r::to_json(&r::Val::List(vec![r::field(row, "user_id")])),
                        data: serde_json::Value::Object(data),
                        trigger: "UserQuota.on_enter exceeded".to_string(),
                    };
                    write.stage(request.record("UserQuota", &aggregate_id, company, write)).await?;
                }
                self.triggers.on_enter_exceeded__send_email_quota_exceeded(write, change.before().unwrap_or(subject), subject).await?;
                tracing::info!(target: "backbone::trigger", trigger = "UserQuota.on_enter exceeded", correlation_id = %write.correlation_id, log_event = "quota.exceeded", user_id = %r::to_json(&r::field(row, "user_id")));
                self.triggers.on_enter_exceeded__emit_quota_exceeded_event(write, change.before().unwrap_or(subject), subject).await?;
            }
            Ok(())
        })
        .await?;

        Ok(())
    }
}
